[
  {
    "title": "pH 的對數尺度",
    "body": "pH = −log₁₀[H⁺]；氫離子濃度增加十倍，pH 就降低 1。",
    "examples": [
      "[H⁺] = 10⁻³ mol/L 時，pH = 3。"
    ]
  },
  {
    "title": "中性不一定是 pH 7",
    "body": "中性只表示 [H⁺] = [OH⁻]，不保證 pH 等於 7；水的離子積會隨溫度改變。",
    "examples": [
      "50°C 時，中性水的 pH 約為 6.6。"
    ]
  },
  {
    "title": "酸的強弱不等於濃度",
    "body": "酸的強弱由解離平衡與 Ka 決定，和溶液濃度不同；濃醋酸仍可能比稀鹽酸含有更多氫離子。",
    "examples": [
      "稀鹽酸的酸性可能強於濃醋酸，因鹽酸解離較完全。"
    ]
  }
]
